<?php
declare(strict_types=1);
use DigiForge\Orders\PersonalizationCurrentness;
use DigiForge\POD\{CustomerEditorRepository,CustomerPhotoSelection};
// Candidate-only c2f assessment: valid public primes occur before caller TX; caller TX remains owned by the test.
require_once dirname(__DIR__,4).'/tests/wordpress/CustomerPhotoHeldIntegrationTest.php';
final class CustomerPhotoOwnerCurrentReadFailureReproTest extends CustomerPhotoHeldIntegrationTest {
 public function testActualProducerSelectionCannotRemainOldAcrossCommittedSamePixelRevision():void {
  $f=$this->photo();$actor=get_current_user_id();$photo=new CustomerPhotoSelection();global $wpdb;$primary=$wpdb;$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$other->set_prefix($primary->prefix);$modes=['READ-COMMITTED'=>'READ COMMITTED','REPEATABLE-READ'=>'REPEATABLE READ','READ-UNCOMMITTED'=>'READ UNCOMMITTED','SERIALIZABLE'=>'SERIALIZABLE'];$prior=strtoupper((string)$primary->get_var('SELECT @@session.tx_isolation'));self::assertArrayHasKey($prior,$modes);$marker='digiforge_candidate_caller_pending_'.wp_generate_uuid4();$next=null;
  try {self::assertNotFalse($primary->query('COMMIT'));self::assertNotFalse($primary->query('SET autocommit=1'));self::assertNotFalse($primary->query('SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ'));self::assertSame($f['selection']['sha256'],PrintifyApiApprovalFixture::checked($photo->forOrder('personalized_pod',$f['order'],$f['line']))['sha256']);self::assertNotFalse($primary->query('START TRANSACTION WITH CONSISTENT SNAPSHOT'));self::assertSame(1,$primary->insert($primary->comments,['comment_content'=>$marker,'comment_agent'=>'pending']));$first=$photo->forOrder('personalized_pod',$f['order'],$f['line']);self::assertWPError($first);self::assertSame('photo_current_read_caller_transaction',$first->get_error_code());self::assertSame('1',(string)$primary->get_var('SELECT @@session.in_transaction'));self::assertSame('pending',$primary->get_var($primary->prepare('SELECT comment_agent FROM '.$primary->comments.' WHERE comment_content=%s',$marker)));
   $wpdb=$other;self::assertNotFalse($other->query('SET SESSION innodb_lock_wait_timeout=2'));wp_set_current_user($f['customer']);$request=$f['request'];$request['request_key']='two-connection-same-photo';$request['expected_head']=$f['version']['sha256'];$version=PrintifyApiApprovalFixture::checked((new CustomerEditorRepository())->upload($f['session'],$request));$next=PrintifyApiApprovalFixture::checked($photo->submit($f['session'],$version['sha256'],1));wp_set_current_user($actor);PrintifyApiApprovalFixture::checked($photo->review($f['session'],$next['sha256'],2,'APPROVED','Synthetic independently committed second selection'));self::assertSame('0',(string)$other->get_var('SELECT @@session.in_transaction'));$fresh=PrintifyApiApprovalFixture::checked($photo->forOrder('personalized_pod',$f['order'],$f['line']));self::assertSame($next['sha256'],$fresh['sha256']);self::assertSame($f['selection']['submission_id'],$next['submission_id']);self::assertNotSame($f['selection']['sha256'],$next['sha256']);
   $wpdb=$primary;$stale=$photo->forOrder('personalized_pod',$f['order'],$f['line']);self::assertWPError($stale,'A caller snapshot must be denied after an independently committed epoch.');self::assertSame('photo_current_read_caller_transaction',$stale->get_error_code());self::assertSame('1',(string)$primary->get_var('SELECT @@session.in_transaction'));self::assertSame('pending',$primary->get_var($primary->prepare('SELECT comment_agent FROM '.$primary->comments.' WHERE comment_content=%s',$marker)));
  }finally{$wpdb=$primary;$primary->query('ROLLBACK');$markerAfter=$primary->get_var($primary->prepare('SELECT comment_agent FROM '.$primary->comments.' WHERE comment_content=%s',$marker));$primary->delete($primary->comments,['comment_content'=>$marker]);$primary->query('SET autocommit=1');$primary->query('SET SESSION TRANSACTION ISOLATION LEVEL '.$modes[$prior]);$other->query('ROLLBACK');$other->close();wp_set_current_user($actor);self::assertNull($markerAfter,'Only the test-owned rollback removes its uncommitted caller write.');}
 }
 public function testLegacyNullCannotRemainAfterFirstManagedSelectionCommitted():void {
  $f=$this->photo(false);$actor=get_current_user_id();global $wpdb;$primary=$wpdb;$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$other->set_prefix($primary->prefix);$modes=['READ-COMMITTED'=>'READ COMMITTED','REPEATABLE-READ'=>'REPEATABLE READ','READ-UNCOMMITTED'=>'READ UNCOMMITTED','SERIALIZABLE'=>'SERIALIZABLE'];$prior=strtoupper((string)$primary->get_var('SELECT @@session.tx_isolation'));self::assertArrayHasKey($prior,$modes);$marker='digiforge_candidate_caller_pending_'.wp_generate_uuid4();
  try{$primary->query('COMMIT');$primary->query('SET autocommit=1');$primary->query('SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ');self::assertNull((new CustomerPhotoSelection())->resolveForOrder('personalized_pod',$f['order'],$f['line']));self::assertNotWPError((new PersonalizationCurrentness())->forOrder($f['order']));$primary->query('START TRANSACTION WITH CONSISTENT SNAPSHOT');self::assertSame(1,$primary->insert($primary->comments,['comment_content'=>$marker,'comment_agent'=>'pending']));$initial=(new PersonalizationCurrentness())->forOrder($f['order']);self::assertWPError($initial);self::assertSame('photo_current_read_caller_transaction',$initial->get_error_code());self::assertSame('1',(string)$primary->get_var('SELECT @@session.in_transaction'));self::assertSame('pending',$primary->get_var($primary->prepare('SELECT comment_agent FROM '.$primary->comments.' WHERE comment_content=%s',$marker)));
   $wpdb=$other;$other->query('SET SESSION innodb_lock_wait_timeout=2');wp_set_current_user($f['customer']);$version=PrintifyApiApprovalFixture::checked((new CustomerEditorRepository())->upload($f['session'],$f['request']));$selection=PrintifyApiApprovalFixture::checked((new CustomerPhotoSelection())->submit($f['session'],$version['sha256'],0));wp_set_current_user($actor);PrintifyApiApprovalFixture::checked((new CustomerPhotoSelection())->review($f['session'],$selection['sha256'],1,'APPROVED','Synthetic first independently committed managed selection'));self::assertSame('0',(string)$other->get_var('SELECT @@session.in_transaction'));self::assertSame($selection['sha256'],PrintifyApiApprovalFixture::checked((new CustomerPhotoSelection())->resolveForOrder('personalized_pod',$f['order'],$f['line']))['sha256']);
   $wpdb=$primary;$denied=(new PersonalizationCurrentness())->forOrder($f['order']);self::assertWPError($denied,'An old nullable legacy snapshot must not authorize legacy input after the first managed selection commits.');self::assertSame('photo_current_read_caller_transaction',$denied->get_error_code());self::assertSame('1',(string)$primary->get_var('SELECT @@session.in_transaction'));self::assertSame('pending',$primary->get_var($primary->prepare('SELECT comment_agent FROM '.$primary->comments.' WHERE comment_content=%s',$marker)));
  }finally{$wpdb=$primary;$primary->query('ROLLBACK');$markerAfter=$primary->get_var($primary->prepare('SELECT comment_agent FROM '.$primary->comments.' WHERE comment_content=%s',$marker));$primary->delete($primary->comments,['comment_content'=>$marker]);$primary->query('SET autocommit=1');$primary->query('SET SESSION TRANSACTION ISOLATION LEVEL '.$modes[$prior]);$other->query('ROLLBACK');$other->close();wp_set_current_user($actor);self::assertNull($markerAfter,'Only the test-owned rollback removes its uncommitted caller write.');}
 }
}
